from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    rare = {color for color, count in counts.items() if count <= 0.15 * h * w}
    neighbor_votes = Counter()
    for r in range(h):
        for c in range(w):
            if grid[r][c] in rare:
                for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
                    if 0 <= nr < h and 0 <= nc < w:
                        neighbor_votes[grid[nr][nc]] += 1
    line_color = neighbor_votes.most_common(1)[0][0]
    marker_rows = [r for r, row in enumerate(grid) if any(v in rare for v in row)]
    line_cols = [c for c in range(w) if sum(grid[r][c] == line_color for r in range(h)) >= 0.60 * h]
    base = counts.most_common(1)[0][0]
    out = []
    for r0, r1 in zip(marker_rows, marker_rows[1:]):
        line = []
        for c0, c1 in zip(line_cols, line_cols[1:]):
            corners = [grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1]]
            if corners[0] in rare and all(v == corners[0] for v in corners):
                line.append(corners[0])
            else:
                line.append(base)
        out.append(line)
    return out

